import{_ as n,l as s,o as e,c as l,v as t,p as o,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"Sanitizers","description":"","frontmatter":{"title":"Sanitizers","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sanitizers.md","filePath":"cs/sanitizers.md","lastUpdated":1789023840000}'),c={name:"cs/sanitizers.md"};function A(S,a,_,u,f,m){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="sanitizers" tabindex="-1">Sanitizers <a class="header-anchor" href="#sanitizers" aria-label="Permalink to &quot;Sanitizers&quot;">​</a></h1><div class="epigraph"><p>ASan 在影子内存里记账，越界与 UAF 变成立即中止；UBSan 抓未定义；MSan 抓未初始化。它们是测试时的预言，不是生产默认的零开销证明。</p><footer>—— Serebryany et al., AddressSanitizer, USENIX ATC 2012；对照 LLVM sanitizer 文档</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/static-taint-analysis">污点</a>是流规则。缺口是<strong>把空间错误变成确定崩溃</strong>，好让 fuzz 停下来。本课收 ASan/MSan/UBSan/TSan 的分工，不讲如何绕过 ASan。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无 sanitizer 时溢出可能「看起来能跑」。ASan：红区与延迟释放。TSan：数据竞争。缺口是：要进 CI；生产用不同工具（GWP-ASan 抽样点名）。</p><h3 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h3><p>完整 ASan 不宜当默认生产配置。发现阶段与发布阶段分开。</p><p><span class="marginnote">Serebryany et al. 2012。本课禁止利用未开 sanitizer 的差异写 exploit。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表状叙述四种。要求 fuzz 目标链 ASan。对照硬件缓解：一边发现，一边上线硬化。下一课浏览器沙箱：即使有洞也难出进程。</p>',12)),(e(),o(h,null,{default:i(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FUZZ%5B%22fuzz%20%E8%BE%93%E5%85%A5%22%5D%20--%3E%20ASAN%5B%22ASan%20%E4%B8%AD%E6%AD%A2%22%5D%0A%20%20ASAN%20--%3E%20BUG%5B%22%E5%8F%AF%E5%9B%9E%E5%BD%92%E7%BC%BA%E9%99%B7%22%5D%0A%20%20PROD%5B%22%E7%94%9F%E4%BA%A7%22%5D%20--%3E%20MITIG%5B%22CET%2FPAC%2F%E6%B2%99%E7%AE%B1%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现课把洞变成票。沙箱下一课把爆炸半径从「全用户」收到「渲染进程」。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写关闭 ASan 的技巧。浏览器沙箱下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>污点是流；sanitizer 是空间/并发预言。</li><li>fuzz 应开 ASan；生产靠缓解与抽样。</li><li>立即中止优于静默损坏。</li><li>下一课浏览器沙箱。</li><li>出处：Serebryany et al., ATC 2012；LLVM Sanitizers。</li></ul>',8))])}const B=n(c,[["render",A]]);export{E as __pageData,B as default};
